description:
Implement a `useIdle` hook that returns `true` when the user has been inactive for `timeout` ms, and resets to `false` when they interact again. Listen to `mousemove`, `keydown`, `mousedown`, and `touchstart` events on the document.

**Example:**
```tsx
const isIdle = useIdle(30_000);
if (isIdle) lockScreen();
```

starter_code:
import { useEffect, useState, useRef } from 'react';

export function useIdle(timeout: number): boolean {
  // your code here
}

test_suite:
test('returns false initially', () => {
  vi.useFakeTimers();
  const { result } = renderHook(() => useIdle(1000));
  expect(result.current).toBe(false);
  vi.useRealTimers();
});

test('returns true after timeout with no activity', () => {
  vi.useFakeTimers();
  const { result } = renderHook(() => useIdle(1000));
  act(() => vi.advanceTimersByTime(1000));
  expect(result.current).toBe(true);
  vi.useRealTimers();
});

test('resets to false on mousemove', () => {
  vi.useFakeTimers();
  const { result } = renderHook(() => useIdle(1000));
  act(() => vi.advanceTimersByTime(1000));
  expect(result.current).toBe(true);
  act(() => document.dispatchEvent(new MouseEvent('mousemove')));
  expect(result.current).toBe(false);
  vi.useRealTimers();
});

test('resets to false on keydown', () => {
  vi.useFakeTimers();
  const { result } = renderHook(() => useIdle(1000));
  act(() => vi.advanceTimersByTime(1000));
  act(() => document.dispatchEvent(new KeyboardEvent('keydown')));
  expect(result.current).toBe(false);
  vi.useRealTimers();
});

// __hidden__
test('removes listeners on unmount', () => {
  vi.useFakeTimers();
  const spy = vi.spyOn(document, 'removeEventListener');
  const { unmount } = renderHook(() => useIdle(1000));
  unmount();
  expect(spy).toHaveBeenCalled();
  spy.mockRestore();
  vi.useRealTimers();
});

solution:
import { useEffect, useState, useRef, useCallback } from 'react';

export function useIdle(timeout: number): boolean {
  const [idle, setIdle] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const reset = useCallback(() => {
    setIdle(false);
    if (timerRef.current) clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => setIdle(true), timeout);
  }, [timeout]);

  useEffect(() => {
    const events = ['mousemove', 'keydown', 'mousedown', 'touchstart'];
    events.forEach(e => document.addEventListener(e, reset));
    reset();
    return () => {
      events.forEach(e => document.removeEventListener(e, reset));
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [reset]);

  return idle;
}
